    ["VU"] = "VISTO",
    ["vu crafter (sans l'addon)"] = "visto fabricando (sin el addon)",
    ["vu crafter"] = "visto fabricando",
    ["%d+ · vu crafter"] = "%d+ · visto fabricando",
    -- Cooldowns de recettes (transmutations & co)
    ["%s : prête"] = "%s: lista",
    ["%s : dans %s"] = "%s: en %s",
    ["(estimé)"] = "(estimado)",
    ["Transmutation"] = "Transmutación",
    ["%dj"] = "%dd", ["%dh"] = "%dh", ["%dmin"] = "%dmin",
    -- Relais partenaire
    ["via %s · il y a %s"] = "vía %s · hace %s",
    ["RELAIS"] = "RELEVO",
    -- Rerolls (identité joueur multi-persos, /co alts — opt-in)
    ["rerolls : ACTIVÉS — ta liste de persos est annoncée au réseau."] =
        "alters: ACTIVADOS — tu lista de personajes se anuncia a la red.",
    ["rerolls : désactivés — rien n'est annoncé (opt-in : /co alts on)."] =
        "alters: desactivados — no se anuncia nada (opt-in: /co alts on).",
    ["perso principal (vitrine) : %s"] = "personaje principal (escaparate): %s",
    ["persos du compte (%s) : %s"] = "personajes de la cuenta (%s): %s",
    ["le lien n'est vérifié chez les autres qu'après une connexion de CHAQUE perso (addon actif)."] =
        "los demás solo verifican el vínculo cuando CADA personaje se ha conectado una vez (addon activo).",
    ["rerolls activés — perso principal : %s (changer : /co alts main <nom>)"] =
        "alters activados — personaje principal: %s (cambiar: /co alts main <nombre>)",
    ["rerolls désactivés — dissolution annoncée au réseau."] =
        "alters desactivados — disolución anunciada a la red.",
    ["perso inconnu sur ce compte : %s (connecte-le une fois avec l'addon)"] =
        "personaje desconocido en esta cuenta: %s (conéctalo una vez con el addon)",
    ["regrouper tes rerolls (opt-in) : liste annoncée, commandes routées vers ton perso connecté"] =
        "agrupar tus alters (opt-in): lista anunciada, pedidos dirigidos a tu personaje conectado",
    ["commande nommée pour %s : connecte ce perso, ou active /co alts on pour accepter d'ici."] =
        "pedido dirigido a %s: conecta ese personaje, o activa /co alts on para aceptar desde aquí.",
    ["|cFFFFCC00commande pour ton reroll %s|r de |cFFFFFFFF%s|r : %s%s%s"] =
        "|cFFFFCC00pedido para tu alter %s|r de |cFFFFFFFF%s|r: %s%s%s",
    ["En ligne via %s"] = "En línea vía %s",
    ["reroll : %s (%s)"] = "alter: %s (%s)",
    -- v1.31.0
    ["Les cercles d'artisans, posés sur les communautés WoW"] =
        "Círculos de artesanos, apoyados en las comunidades de WoW",
    ["Le canal du royaume n'a ni mémoire ni liste de membres : qui n'était pas connecté quand tu as posté n'a rien vu, et chaque session recommence à chercher qui est là. Une communauté WoW répond aux deux. Marque-la avec /co circle et ses membres apparaissent sous « Cercle » dans l'onglet Artisans, avec leur présence, y compris ceux qui sont hors ligne. C'est toi qui crées la communauté et qui invites : un cercle est un petit groupe que tu as choisi, pas le royaume entier."] =
        "El canal del reino no tiene memoria ni lista de miembros: quien no estaba conectado cuando publicaste no vio nada, y cada sesión vuelve a empezar buscando quién anda por ahí. Una comunidad de WoW resuelve ambas cosas. Márcala con /co circle y sus miembros aparecen bajo « Círculo » en la pestaña Artesanos, con su presencia, incluidos los que están desconectados. Tú creas la comunidad y tú invitas a quien quieres: un círculo es un grupo pequeño que has elegido, no el reino entero.",
    ["Rien n'est posté dans la communauté et rien n'en est lu. Ce qu'une communauté peut réellement porter a été mesuré avant qu'on s'appuie dessus, et c'est étroit : le texte d'un message de club est illisible depuis un addon, et un message addon envoyé sur son canal est accepté puis jeté. Le cercle te donne donc la liste et qui est en ligne ; les commandes et les niveaux de métier continuent de circuler exactement comme avant."] =
        "No se publica nada en la comunidad ni se lee nada de ella. Lo que una comunidad puede llevar de verdad se midió antes de apoyarse en ella, y es poco: el texto de un mensaje de club no se puede leer desde un addon, y un mensaje de addon enviado a su canal se acepta y luego se descarta. Así que el círculo te da la lista y quién está conectado; los pedidos y los niveles de profesión siguen viajando igual que antes.",
    ["Les métiers ne viennent pas non plus de la communauté : ces champs-là ne sont remplis que pour un roster de guilde. Un membre de cercle affiche ses métiers quand il répond à l'addon, comme tout le monde."] =
        "Las profesiones tampoco vienen de la comunidad: esos campos solo se rellenan para las listas de hermandad. Un miembro del círculo muestra sus profesiones cuando responde al addon, como todo el mundo.",
    -- v1.31.1
    ["Les nouveaux venus apparaissent tout seuls"] =
        "Los recién llegados aparecen solos",
    ["Quelqu'un qui venait d'installer l'addon restait invisible tant qu'il ne cliquait pas « Rafraîchir l'annuaire » — ce que personne ne pense à faire devant un annuaire qui a l'air vide, et avoir l'air vide était justement le problème."] =
        "Quien acababa de instalar el addon seguía invisible hasta que pulsaba « Actualizar directorio », algo que nadie piensa en hacer ante un directorio que parece vacío, y parecer vacío era justo el problema.",
    ["À la connexion, l'addon ne s'annonçait que sur le canal caché du royaume, le moins fiable de ses moyens d'atteindre les autres. L'annonce qui touche vraiment les inconnus n'a le droit de partir que juste après un clic ou une touche : à la connexion il n'y avait donc aucun moment pour l'envoyer, et elle était jetée au lieu d'être gardée. Elle attend maintenant, et part à ton premier clic ou ta première touche — quelques secondes, sans que tu fasses quoi que ce soit. La connexion sonde aussi directement les joueurs autour de toi, ce que le bouton « Rafraîchir » faisait déjà et pas elle."] =
        "Al conectarte, el addon solo te anunciaba en el canal oculto del reino, el menos fiable de sus medios para llegar a los demás. El anuncio que sí alcanza a los desconocidos solo puede salir justo después de un clic o una tecla: al conectarte no había momento para enviarlo, así que se descartaba en vez de guardarse. Ahora espera y sale con tu primer clic o tecla, unos segundos, sin que hagas nada. La conexión también sondea directamente a los jugadores a tu alrededor, algo que el botón Actualizar ya hacía y la conexión no.",
    -- v1.32.0
    ["Forever lit enfin tes métiers et tes recettes"] =
        "Forever por fin lee tus profesiones y recetas",
    ["Sur WoW: Forever, l'addon ne voyait pas tes métiers : Forever tourne sur l'API du jeu moderne, et les fonctions qui lisaient tes compétences n'y existent pas. Rien ne plantait. L'annuaire t'annonçait simplement sans aucun métier, le clic droit disait que tu n'en avais pas, et « Mes artisans » restait vide. Tes recettes connues et leurs temps de recharge avaient le même problème. Tout est lu à la manière de Forever maintenant."] =
        "En WoW: Forever el addon no veía tus profesiones. Forever funciona con la API del juego moderno, y las funciones que leían tus habilidades no existen allí. No salía ningún error. El directorio simplemente te anunciaba sin profesiones, el clic derecho decía que no tenías ninguna y «Mis artesanos» se quedaba vacío. Tus recetas conocidas y sus tiempos de reutilización tenían el mismo problema. Ahora todo se lee a la manera de Forever.",
    ["Quand quelqu'un te cible dans l'onglet Commande, il voit ce que tu sais vraiment faire, plus une estimation. Et l'estimation elle-même était trop généreuse : une recette sans niveau connu comptait comme atteignable, si bien qu'un couturier niveau 13 se voyait proposer des pièces Stormcloth qui demandent le niveau 40. Un niveau inconnu veut dire « pas proposé » désormais."] =
        "Cuando alguien te elige en la pestaña Pedir, ve lo que sabes hacer de verdad, ya no una estimación. Y la estimación era demasiado generosa: una receta sin nivel conocido contaba como alcanzable, así que a un sastre de nivel 13 se le ofrecían piezas de Stormcloth que piden nivel 40. Ahora, nivel desconocido significa que no se ofrece.",
    ["La liste des recettes est celle de Forever : 2512 recettes tirées des pages Forever de Wowhead, au lieu des 1230 de vanilla. Forever a déplacé des choses, et les potions de soin sont maintenant en Secourisme, plus en Alchimie."] =
        "La lista de recetas es la de Forever: 2512 recetas sacadas de las páginas de Forever de Wowhead en lugar de las 1230 de vanilla. Forever ha movido cosas, y las pociones de sanación están ahora en Primeros auxilios, no en Alquimia.",
    ["Sur Forever, le clic droit sur le bouton de la minimap ouvre la fenêtre des métiers du jeu. Les métiers de tes rerolls se consultent désormais depuis « Mes artisans » (clic droit sur un métier). /co mute accepte les noms en prénom et nom, entre guillemets si l'addon n'a pas encore croisé le joueur."] =
        "En Forever, el clic derecho en el botón del minimapa abre la ventana de profesiones del juego. Las profesiones de tus alters se consultan ahora en «Mis artesanos» (clic derecho sobre una profesión). /co mute acepta nombre y apellido, entre comillas si el addon aún no ha visto a ese jugador.",
    -- v1.32.1
    ["La fenêtre de métier de Forever cesse de se plaindre"] =
        "La ventana de profesiones de Forever deja de quejarse",
    ["Sur WoW: Forever, la colonne des commandes s'invite dans la fenêtre de métier du jeu. Elle y est l'hôte d'un cadre que le jeu protège, et presque tout ce qu'elle y faisait était refusé dès que tu étais en combat : ouvrir ou fermer la fenêtre pendant un combat déclenchait une volée d'erreurs « action bloquée », avec l'addon nommé au passage. La colonne ne touche plus au cadre pendant le combat, et reprend sa place à la fin."] =
        "En WoW: Forever, la columna de pedidos se instala dentro de la ventana de profesiones del juego. Allí es huésped de un marco que el juego protege, y casi todo lo que hacía se rechazaba en cuanto entrabas en combate. Abrir o cerrar la ventana en plena pelea lanzaba una tanda de errores de acción bloqueada, con el addon señalado por su nombre. Ahora la columna no toca el marco durante el combate y recupera su sitio al terminar.",
    ["Elle s'affiche aussi quand il faut. Il fallait deux passages : la fenêtre s'ouvre sur la page d'ensemble, où il n'y a aucun métier courant et donc rien à lister, si bien que la première visite semblait vide. Elle apparaît maintenant dès que tu es sur un métier, du premier coup."] =
        "También aparece cuando debe. Antes hacían falta dos intentos: la ventana abre en la página de resumen, donde no hay profesión actual y por tanto nada que listar, así que la primera visita parecía vacía. Ahora aparece en cuanto estás en una profesión, a la primera.",
    ["Le reste : on ne peut plus la sortir de la fenêtre en la tirant, sa place appartient à son hôte ; les onglets de métier de Blizzard ne recouvrent plus son dernier onglet ; /co prof cuisine ouvre la Cuisine au lieu de la page d'ensemble ; et l'aide contextuelle n'entoure plus que ce qui est réellement affiché."] =
        "Lo demás: ya no se puede sacar de la ventana arrastrándola, su sitio pertenece a su anfitrión; las pestañas de profesión de Blizzard ya no tapan su última pestaña; /co prof cocina abre Cocina en vez de la página de resumen; y la ayuda solo rodea lo que está realmente en pantalla.",
    -- v1.32.2
    ["Tes barres d'action ne se bloquent plus en combat"] =
        "Tus barras de acción ya no se bloquean en combate",
    ["Sur WoW: Forever, passer d'un onglet à l'autre dans la fenêtre de métier pendant un combat faisait refuser au jeu tout geste sur tes barres d'action, avec l'addon nommé à chaque fois. La fenêtre de métier n'y était pour rien. Deux petites pièces de l'addon l'étaient : ses menus déroulants et son aide « i » empruntaient des systèmes que le jeu partage avec sa propre interface, et s'en servir une seule fois suffisait à marquer cette interface à notre nom jusqu'au prochain rechargement. Les deux sont faits maison maintenant : même rendu, et le jeu n'a plus rien à redire."] =
        "En WoW: Forever, cambiar de pestaña en la ventana de profesiones en pleno combate hacía que el juego se negara a tocar tus barras de acción, y nombraba al addon cada vez. La ventana de profesiones no tenía la culpa. La tenían dos piezas pequeñas del addon: sus menús desplegables y la ayuda de su botón i usaban sistemas que el juego comparte con su propia interfaz, y usarlos una sola vez bastaba para marcar esa interfaz como nuestra hasta la siguiente recarga. Ahora los dos son de fabricación propia: se ven igual y el juego ya no tiene nada que objetar.",
    ["La colonne des commandes peut aussi se poser à côté de la fenêtre de métier plutôt que dedans : /co accole passe d'un mode à l'autre. Dedans reste le mode par défaut."] =
        "La columna de pedidos también puede colocarse junto a la ventana de profesiones en lugar de dentro: /co accole alterna entre los dos modos. Dentro sigue siendo el modo por defecto.",
    ["Petites retouches : une longue liste de stats ne sort plus par le bas de l'écran, et chaque liste prend la largeur de sa plus longue entrée ; la liste des canaux de la fenêtre de partage des composants s'ouvre au-dessus d'elle et non plus dessous ; et l'aide suit la fenêtre si le jeu la déplace pendant qu'elle est ouverte."] =
        "Pequeños arreglos: una lista larga de estadísticas ya no se sale por abajo de la pantalla, y cada lista es tan ancha como su entrada más larga; la lista de canales de la ventana para compartir componentes se abre encima de esa ventana y no detrás; y la ayuda sigue a la ventana si el juego la mueve mientras está abierta.",
    -- v1.33.0
    ["D'où vient une recette, sans MTSL"] = "De dónde viene una receta, sin MTSL",
    ["L'addon ne réclame plus MTSL. Sa base décrit Vanilla et TBC, or Forever a refait les tables d'objets dessous : 894 objets-recette qui n'existent que là, 173 disparus de Classic, et 24 identifiants communs qui désignent aujourd'hui un tout autre objet. Un annuaire périmé est pire qu'un annuaire absent, parce qu'il répond avec assurance. Les sources de recettes viennent maintenant de nos propres données, tirées des pages Forever de Wowhead."] =
        "El addon ya no pide MTSL. Su base describe Vanilla y TBC, pero Forever rehízo las tablas de objetos por debajo: 894 objetos-receta que solo existen allí, 173 de Classic que han desaparecido, y 24 identificadores comunes que hoy designan un objeto completamente distinto. Un directorio caducado es peor que ninguno, porque responde con seguridad. Las fuentes de recetas salen ahora de nuestros propios datos, generados desde las páginas Forever de Wowhead.",
    ["Survole une recette que tu n'as pas apprise : elle te dit si le plan tombe en butin, s'il se vend ou s'il vient d'une quête, et elle nomme le PNJ et la zone quand elle les connaît. Sur Forever, le jeu le dit mieux que nous : sa formulation l'emporte dès qu'il en a une. Une recette de formateur est une déduction et non un fait, alors elle porte un « ? » plutôt que de faire semblant."] =
        "Pasa el ratón por una receta que no hayas aprendido: te dice si el plano cae como botín, se vende o viene de una misión, y nombra al PNJ y la zona cuando los conoce. En Forever el juego lo dice mejor que nosotros, así que su redacción gana en cuanto tiene una. Una receta de entrenador es una deducción y no un hecho, así que lleva un signo de interrogación en vez de fingir lo contrario.",
    ["Le Plan de route remarche sur Forever, chiffré sur ton dernier scan Auctionator (Lazy Gold reste sur l'Era). Et la colonne des commandes change de contenu au lieu d'ouvrir des fenêtres par-dessus elle : trois onglets en haut, Commandes, Plan de route et Manquantes. Manquantes liste toutes les recettes que tu n'as pas apprises avec le rang qu'elles demandent, grisées tant que tu ne peux pas les prendre."] =
        "La ruta de subida vuelve a funcionar en Forever, calculada con tu último escaneo de Auctionator (Lazy Gold sigue para Era). Y la columna de pedidos cambia de contenido en vez de abrir ventanas encima: tres pestañas arriba, Pedidos, Ruta de subida y Faltantes. Faltantes lista todas las recetas que no has aprendido con el nivel que piden, en gris hasta que puedas cogerlas.",
    ["Corrections : sur Forever la colonne comptait comme connues des recettes non apprises, et la route, les badges et ce que les autres artisans voyaient de toi reposaient là-dessus ; les prix sortaient vides ; la carte d'une commande sélectionnée était dessinée pour une fenêtre moitié plus large que la colonne, donc sa croix, son prix et le bord droit du panneau des composants étaient coupés ; une commande d'enchantement affichait « ? » au lieu de son nom."] =
        "Correcciones: en Forever la columna contaba como conocidas recetas no aprendidas, y la ruta, las insignias y lo que los demás artesanos veían de ti se apoyaban en eso; los precios salían vacíos; la ficha de un pedido seleccionado estaba dibujada para una ventana bastante más ancha que la columna, así que su aspa, su precio y el borde derecho del panel de componentes quedaban cortados; un pedido de encantamiento mostraba un signo de interrogación en vez de su nombre.",
    ["L'onglet Manquantes te dit enfin où aller"] =
        "La pestaña Faltantes por fin te dice adónde ir",
    ["Survoler une recette que tu n'as pas te donnait son nom et son rang, c'est-à-dire ce que la ligne affichait déjà. Tu as maintenant l'infobulle de l'objet lui-même, puis ce qu'il te manque en points de métier, si la recette rapporte encore quelque chose à ton rang, et d'où vient le plan."] =
        "Pasar el ratón por una receta que no tienes te daba su nombre y su rango, es decir lo que la línea ya mostraba. Ahora aparece primero el tooltip del objeto del propio juego, y debajo cuánta habilidad te falta, si la receta todavía da un punto a tu rango, y de dónde sale el plano.",
    ["Ce dernier point a beaucoup changé. L'addon connaissait un seul nom par plan et rien de son camp : « Recipe: Gingerbread Cookie » envoyait tout le monde chez Wulmort Jinglepocket, à Forgefer, Horde comprise. 1565 recettes nomment quelqu'un contre 337 avant, le marchand affiché est de ta faction, 719 donnent le prix réel du marchand sans aucun addon de prix, et 846 PNJ ont des coordonnées : un clic pose un repère, ce qui ne marchait plus depuis MTSL."] =
        "Eso último ha cambiado mucho. El addon conocía un solo nombre por plano y nada sobre su bando, así que «Recipe: Gingerbread Cookie» mandaba a todo el mundo a Wulmort Jinglepocket en Forjaz, Horda incluida. 1565 recetas nombran a alguien frente a 337 antes, el vendedor que ves es de tu facción, 719 dan el precio real del mercader sin ningún addon de precios, y 846 PNJ traen coordenadas: un clic deja un punto de ruta, algo que no funcionaba desde que se fue MTSL.",
    ["Les formateurs. Aucune page ne dit « ça s'apprend au formateur » : l'addon le déduisait de l'absence d'objet-recette et affichait un point d'interrogation, sur 788 recettes. Wowhead le publie en fait sur la page du sort et pas celle de l'objet, ce qui en a nommé 398. Et quand tu parles à un formateur de métier, l'addon note ce qu'il enseigne et où il se tient : le point d'interrogation disparaît et tu récupères ses coordonnées. Si ta fenêtre de formateur filtre ce qu'elle affiche, il te le dit au lieu de n'en moissonner qu'un tiers en silence."] =
        "Y los maestros. Ninguna página dice «esto se aprende con el maestro»: el addon lo deducía de la ausencia de objeto-receta y mostraba un interrogante, en 788 recetas. Wowhead sí lo publica, en la página del hechizo y no en la del objeto, lo que dio nombre a 398. Y cuando hablas con un maestro de profesión, el addon anota qué enseña y dónde está: el interrogante desaparece y te quedas con sus coordenadas. Si tu ventana de maestro está filtrando lo que muestra, te lo dice en vez de recoger solo un tercio en silencio.",
    ["Corrigé : un plantage en donjon (le client rend des valeurs « secrètes » pour certaines données d'unité, et l'une d'elles finissait en clé de table trois appels plus loin, dans une fonction d'annuaire qui n'avait aucune raison de se méfier d'un nom), et le changement d'onglet de métier qui laissait la liste d'un métier avec les infobulles d'un autre."] =
        "Corregido: un cuelgue en mazmorras (el cliente devuelve valores «secretos» para ciertos datos de unidad, y uno acababa de clave de tabla tres llamadas más tarde, en una función de directorio que no tenía por qué desconfiar de un nombre), y el cambio de pestaña de profesión que dejaba la lista de una profesión con los tooltips de otra.",
    -- v1.35.1
    ["Un niveau qu'on ne connaît pas n'est pas un niveau 0"] =
        "Un nivel que no conocemos no es un cero",
    ["La vue Manquantes plaçait huit recettes de Couture en tête de liste en te disant qu'elles étaient à ta portée, affichées « niveau requis 0 ». 29 recettes réparties sur six métiers n'ont aucun niveau dans les données, et l'addon lisait cette absence comme un zéro — qui se classe en tête et passe tous les tests de « peux-tu l'apprendre »."] =
        "La vista Faltantes ponía ocho recetas de Sastrería al principio de la lista y las declaraba a tu alcance, todas con «nivel requerido 0». 29 recetas de seis profesiones no tienen ningún nivel en los datos, y el addon leía esa ausencia como un cero, que se ordena primero y supera cualquier prueba de «¿ya puedes aprenderlo?».",
    ["Elles affichent « ? » maintenant, elles descendent en fin de liste, et l'addon ne les dit ni à ta portée ni hors de portée, puisqu'il l'ignore. L'infobulle le dit franchement. Les niveaux eux-mêmes manquent toujours : c'est un travail de données, pas d'affichage."] =
        "Ahora muestran «?», bajan al final de la lista, y el addon no dice ni que están a tu alcance ni que no lo están, porque no lo sabe. La descripción lo dice. Los niveles en sí siguen faltando: eso es trabajo de datos, no de presentación.",
    -- v1.35.0
    ["Enchanter la pièce d'un autre, depuis l'échange"] =
        "Encantar el objeto de otro, desde la ventana de intercambio",
    ["Le panneau flottant d'enchantement a disparu : sur Forever, la fenêtre de métier se dessinait exactement par-dessus. Son rôle revient à la colonne de métier, qui passe en mode Échange dès qu'un échange s'ouvre avec ton Enchantement affiché — la silhouette du partenaire, la pièce qu'il a posée dans l'emplacement « ne sera pas échangé », et ce que ses composants désignent."] =
        "El panel flotante de encantamiento ha desaparecido: en Forever, la ventana de profesión se dibujaba justo encima. Su papel pasa a la columna de profesión, que entra en modo Intercambio en cuanto se abre un intercambio con tu Encantamiento abierto — tu compañero, el objeto que ha puesto en la ranura que no se intercambia, y a qué apuntan sus materiales.",
    ["Clique un emplacement de la silhouette : il reçoit la demande de poser cette pièce (chuchotement, plus une invite d'un clic s'il a l'addon), et la liste de recettes de Blizzard se filtre sur cet emplacement. La main droite coche « Arme » et « Arme à deux mains » à la fois, faute de savoir ce qu'il tient."] =
        "Haz clic en una ranura de la silueta: recibe la petición de poner ese objeto (susurro, más un aviso de un clic si tiene el addon), y la lista de recetas de Blizzard se filtra por esa ranura. La mano derecha marca «Arma» y «Arma a dos manos» a la vez, porque aún no sabemos qué lleva.",
    ["Dès qu'une pièce est posée, la liste suit la pièce elle-même plutôt que ta demande. À la fin de l'échange elle retrouve tes filtres d'avant, y compris celui que tu avais posé toi-même, et la colonne revient sur l'onglet que tu regardais."] =
        "En cuanto hay algo en la mesa, la lista sigue al objeto en sí y no a tu petición. Al terminar el intercambio recupera los filtros que tenías antes, incluido el que hubieras puesto tú, y la columna vuelve a la pestaña que mirabas.",
    ["S'il pose aussi des composants, la colonne nomme l'enchantement qu'ils désignent — elle lit ce qu'il pose, jamais tes sacs, et se tait quand plusieurs enchantements collent. Et si un échange s'ouvre alors que ton Enchantement est fermé, un onglet apparaît au bord droit de la fenêtre d'échange pour l'ouvrir."] =
        "Si además pone materiales, la columna nombra el encantamiento al que apuntan. Lee lo que él pone, nunca tus bolsas, y calla cuando encajan varios encantamientos. Y si se abre un intercambio con el Encantamiento cerrado, aparece una pestaña en el borde derecho de la ventana de intercambio para abrirlo.",
    -- v1.34.1
    ["Plus d'erreur en entrant en ville"] =
        "Se acabó el error al entrar en una ciudad",
    ["Avec la détection des artisans sans l'addon activée (/co crafters on), chaque entrée en ville déclenchait une erreur « action interdite » au nom de l'addon. Sur Forever, le jeu n'autorise plus les addons à écouter le journal de combat, et l'addon s'y abonnait quand même. C'est fini : la détection passe désormais par les messages de fabrication du chat (« Untel crée … »), qui restent ouverts aux addons."] =
        "Con la detección de artesanos activada (/co crafters on), cada entrada en una ciudad provocaba un error de «acción prohibida» con el nombre del addon. En Forever los addons ya no pueden escuchar el registro de combate, y el addon lo seguía intentando. Ya no: la detección pasa ahora por los mensajes de fabricación del chat («X crea Y»), que los addons sí pueden leer.",
    ["Le panneau d'enchantement qui s'ouvre à côté de la fenêtre d'échange disait toujours « Ouvre ta fenêtre d'Enchantement », même ouverte : il cherchait une fenêtre qui n'existe pas sur Forever. Il liste maintenant tes enchantements pour la pièce posée, classés comme avant, et il remarque quand tu ouvres l'Enchantement en plein échange. Cliquer une ligne ne lance pas encore l'enchantement."] =
        "El panel de encantamiento que se abre junto a la ventana de comercio siempre decía «Abre tu ventana de Encantamiento», aunque estuviera abierta: buscaba una ventana que no existe en Forever. Ahora muestra tus encantamientos para la pieza colocada, ordenados como antes, y se da cuenta cuando abres Encantamiento en mitad de un intercambio. Hacer clic en una línea todavía no lanza el encantamiento.",
    ["Sous le capot : l'addon ne transporte plus rien du code de Classic Era (cette version reste figée en 1.30.0), et il lit ton journal de quêtes directement dans le jeu, sans passer par les copies des anciennes fonctions que Questie installe quand il est présent."] =
        "Por dentro: el addon ya no lleva nada del código de Classic Era (esa versión sigue congelada en la 1.30.0) y lee tu registro de misiones directamente del juego, en vez de pasar por las copias de las funciones antiguas que Questie instala cuando está presente.",

    -- v1.36.0
    ["Ce qui rapporte, et dire au royaume que tu es dispo"] =
        "Lo que renta, y decirle al reino que estas libre",
    ["La colonne de métier gagne un onglet, Profit : ce que tu sais faire qui vaut la peine d'être fait, la plus grosse marge en haut, avec le prix de vente face au coût des composants. Un clic sur une ligne amène la recette dans la liste de Blizzard. L'onglet n'apparaît que si Auctionator tourne, puisque les prix viennent de lui, et il le dit au lieu de t'afficher un zéro."] =
        "La columna de profesion gana una pestana, Profit. Lista lo que sabes hacer y merece la pena hacer, mayor margen primero, con el precio de venta frente al coste de los reactivos. Un clic en una linea lleva la receta a la lista de Blizzard. La pestana solo aparece si Auctionator esta activo, porque de ahi vienen los precios, y lo dice en vez de mostrarte un cero.",
    ["« Chercher du travail » est revenu. Sur Forever le bouton avait disparu avec l'ancienne fenêtre à trois colonnes : il ne restait que /co lfw, et plus aucun moyen de régler ton offre. C'est maintenant une bande en bas de la colonne, qui affiche « Dispo — Forge » dans toutes les vues. Oublier qu'on est annoncé est exactement ce que le minuteur d'expiration existe pour rattraper."] =
        "'Buscar trabajo' ha vuelto. En Forever el boton habia desaparecido con la antigua ventana de tres columnas, quedaba solo /co lfw y ninguna forma de cambiar tu oferta. Ahora es una banda en la parte inferior de la columna, que muestra 'Disponible, Herreria' en todas las vistas. Olvidar que estas anunciado es justo la razon por la que el anuncio caduca solo.",
    ["À côté, le bouton Offre ouvre ce que tu proposes : les composants de base, une commission par craft, ne prendre que ce qui te fait progresser, les réactifs que tu fournis. Nouveau, tu coches aussi les recettes précises que tu proposes, et qui te consulte les voit par leur nom. La liste des réactifs se limite désormais à ce que tu sais crafter — un travailleur du cuir à 82 ne se voit plus proposer de la Vigne de sang."] =
        "Al lado, un boton Oferta abre lo que estas dispuesto a hacer. Poner los reactivos de vendedor, una comision fija por fabricacion, aceptar solo trabajo que te suba la habilidad, que reactivos aportas. Nuevo, marcas tambien las recetas concretas que ofreces, y quien te consulta las ve por su nombre. Esa lista de reactivos solo muestra lo que de verdad puedes fabricar, asi que a un peletero de 82 ya no se le ofrece Vid sangrienta.",
    ["Recharge ton interface et tu revois les annonces des autres en quelques secondes. Avant, personne ne se ré-annonçait à ton arrivée : tu pouvais rester devant un radar vide pendant huit minutes sans le savoir."] =
        "Recarga la interfaz y los anuncios de los demas vuelven en segundos. Antes nadie se reanunciaba cuando llegabas, asi que podias estar ocho minutos frente a un radar vacio sin saberlo.",
    ["Plus petit. Le bouton d'aide « i » se posait sur la dernière languette et lui volait ses clics. L'onglet « Plan de route » s'appelle « Route », ce qui a fait la place au reste. Et l'addon relève le niveau qu'un formateur exige, donc les recettes affichées « ? » se remplissent à mesure que tu passes les voir."] =
        "Cosas menores. El boton de ayuda 'i' se posaba sobre la ultima pestana y le robaba los clics. La pestana 'Ruta de subida' se llama 'Ruta', que es lo que ha hecho sitio al resto. Y el addon lee el nivel que exige un maestro, asi que las recetas con '?' se rellenan segun las visitas.",

    -- v1.36.1
    ["Une icône dans la liste des addons"] =
        "Un icono en la lista de addons",
    ["L'addon a enfin sa propre icône dans la liste des addons, à la place du point d'interrogation. Rien d'autre ne change."] =
        "El addon por fin tiene su propio icono en la lista de addons, en lugar del signo de interrogación. Nada más cambia.",
    -- v1.36.2
    ["Les commandes trouvent leur destinataire"] =
        "Los pedidos llegan a quien deben",
    ["Sur WoW Forever, chaque personnage a un nom de famille, et le jeu te désigne partout par « Prénom Nom ». L'addon t'appelait par ton prénom seul et ne se reconnaissait plus : une commande à ton nom arrivait puis était ignorée, une commande postée sur le canal était rejetée comme si quelqu'un postait à la place d'un autre, et tu pouvais te retrouver dans ta propre liste d'artisans. C'est réparé, y compris pour les commandes des joueurs restés en 1.36.1."] =
        "En WoW Forever cada personaje tiene apellido, y el juego te llama 'Nombre Apellido' en todas partes. El addon seguía usando solo tu nombre y dejó de reconocerse: un pedido a tu nombre llegaba y se ignoraba, un pedido publicado en el canal se descartaba como si alguien publicara en nombre de otro, y podías aparecer en tu propia lista de artesanos. Corregido, también para los pedidos de jugadores que siguen en la 1.36.1.",
    ["Une ligne du canal Commerce comme « dont need fire wand: [Lesser Magic Wand] » n'est plus prise pour une demande."] =
        "Una línea del canal de Comercio como 'dont need fire wand: [Lesser Magic Wand]' ya no se toma por una petición.",
    -- v1.39.1
    ["Les commandes envoyées par courrier se terminent seules"] =
        "Los pedidos enviados por correo se cierran solos",
    ["Quand un artisan t'envoie ta commande par courrier, prendre l'objet dans ta boîte aux lettres la marque reçue, comme quand tu le ramasses. L'artisan est crédité tout de suite. Avant, elle restait « Remise » et il fallait cliquer « J'ai reçu » dans le Carnet."] =
        "Cuando un artesano te envía tu pedido por correo, sacar el objeto del buzón lo marca como recibido, igual que al despojarlo. El artesano recibe el crédito al momento. Antes se quedaba en 'Entregado' y había que pulsar 'Recibido' en el Libro.",
    ["Côté artisan, « Remplir depuis commande » pouvait joindre une pile entière à une commande plus petite : une commande de 1 partait avec 9. Il coupe maintenant la bonne quantité dans tes sacs et ne joint qu'elle ; sans case libre pour la coupe, le chat te dit combien séparer toi-même."] =
        "Del lado del artesano, 'Rellenar desde pedido' podía adjuntar una pila entera a un pedido más pequeño: un pedido de 1 salía con 9. Ahora separa la cantidad justa en tus bolsas y solo adjunta eso; sin hueco libre para separar, el chat te dice cuántos separar tú mismo.",
    -- v1.39.0
    ["La fenêtre prend l'allure du jeu"] =
        "La ventana se parece al juego",
    ["Les onglets de la fenêtre passent sur son bord droit, en icônes, comme dans la fenêtre de métier. Survole-les pour lire leur nom ; le titre dit où tu es, et l'icône du Carnet compte tes commandes en cours."] =
        "Las pestañas de la ventana pasan a su borde derecho, como iconos, igual que en la ventana de profesión. Pasa el ratón por encima para leer su nombre; el título dice dónde estás, y el icono del Libro cuenta tus pedidos abiertos.",
    ["Toutes les listes et les pages défilent avec la barre fine du jeu, qui se cache quand tout tient : ressources de Récolte, Carnet, Aide, Nouveautés, et les vues Commandes, Route, Manquantes et Profit de la fenêtre de métier. Chaque bloc est posé dans un encart, comme dans la fenêtre de métier."] =
        "Todas las listas y páginas se desplazan con la barra fina del juego, que se oculta cuando todo cabe: recursos de Recolección, Libro, Ayuda, Novedades, y las vistas Pedidos, Ruta, Faltantes y Beneficio de la ventana de profesión. Cada bloque va en un recuadro, como en la ventana de profesión.",
    ["Dans Commande, la commission est la case or, argent, cuivre du jeu, et la quantité a des flèches. Le Carnet se trie : clique l'en-tête d'une colonne, reclique pour inverser. Le Journal et la fiche « Poster en quête » prennent le cadre du journal de quêtes du jeu, livre et parchemin."] =
        "En Pedido, la comisión es la casilla de oro, plata y cobre del juego, y la cantidad tiene flechas. El Libro se ordena: haz clic en el encabezado de una columna, otra vez para invertir. El Diario y la hoja 'Publicar como misión' usan el marco del registro de misiones del juego, con libro y pergamino.",
    ["Les panneaux de l'échange et du courrier prennent l'allure de ces fenêtres. Le courrier ne liste plus que ce qui se poste : un enchantement se fait à l'échange, où l'onglet Enchantement brille quand une commande d'enchant acceptée te lie à ton partenaire. L'Aide est réécrite, et ses flèches affichées en carrés sont réparées."] =
        "Los paneles del comercio y del correo se parecen ahora a esas ventanas. El correo solo lista lo que se puede enviar: un encantamiento se hace en el comercio, donde la pestaña Encantamiento brilla cuando un pedido de encantamiento aceptado te une a tu compañero. La Ayuda está reescrita, y sus flechas que se veían como cuadrados están arregladas.",
    -- v1.38.0
    ["Un signe quand une mise à jour est là"] =
        "Una señal cuando hay una actualización",
    ["Quand le réseau signale une nouvelle version, le logo de Crafting Order apparaît en haut de la minicarte, là où Blizzard pose la lettre du courrier. Survole-le pour voir quelle version est sortie et laquelle tu as, clique pour le détail dans le chat. Il disparaît une fois la mise à jour faite."] =
        "Cuando la red avisa de una versión nueva, el logo de Crafting Order aparece en la parte superior del minimapa, donde Blizzard muestra la carta del correo. Pasa el ratón por encima para ver qué versión ha salido y cuál tienes; un clic muestra los detalles en el chat. Desaparece en cuanto actualizas.",
    -- v1.37.0
    ["Les artisans se retrouvent dans une communauté"] =
        "Los artesanos se reúnen en una comunidad",
    ["Sur WoW Forever, le canal caché de l'addon, CraftLinkNet, est découpé en salles : deux joueurs côte à côte pouvaient ne jamais voir leurs commandes. L'addon ne l'utilise plus, et le quitte si tu y es encore. Les artisans se retrouvent dans la communauté « Crafting Order PVE », une par camp."] =
        "En WoW Forever el canal oculto del addon, CraftLinkNet, se divide en salas separadas: dos jugadores uno al lado del otro podían no ver nunca sus pedidos. El addon ya no lo usa, y lo abandona si sigues dentro. Los artesanos se reúnen ahora en la comunidad 'Crafting Order PVE', una por facción.",
    ["Sans cercle d'artisans, tu reçois à la connexion un whisper de toi-même avec un lien Rejoindre. Clique dessus, puis Rejoindre dans la fenêtre qui s'ouvre : l'addon en fait ton cercle tout seul. « /co circle nolink » coupe ce rappel."] =
        "Sin círculo de artesanos, al conectarte recibes un susurro de ti mismo con un enlace para unirte. Haz clic en él y luego en Unirse en la ventana que se abre: el addon la convierte en tu círculo por sí solo. '/co circle nolink' desactiva este aviso.",
    ["Tout ce qui passait par le canal part en whisper aux joueurs de l'addon en ligne : ton profil, les commandes et leurs annulations, la recherche de travail. Les joueurs restés en 1.36 ne te joignent plus que par les amis, la guilde, un cercle commun ou une commande à leur nom : dis-leur de mettre à jour."] =
        "Todo lo que pasaba por el canal va ahora por susurro a los usuarios del addon conectados: tu perfil, los pedidos y sus cancelaciones, la búsqueda de trabajo. Los jugadores que siguen en la 1.36 solo te alcanzan por amigos, hermandad, un círculo común o un pedido a su nombre: diles que actualicen.",
    ["L'onglet Artisans a une ligne par communauté, à son nom, et un joueur passe hors ligne dès que la communauté le dit parti. La ligne Confédération n'apparaît que si GreenWall tourne."] =
        "La pestaña Artesanos tiene una línea por comunidad, con su nombre, y un jugador pasa a desconectado en cuanto la comunidad dice que se ha ido. La línea Confederación solo aparece si GreenWall está activo.",
    ["Aussi : les listes de Commande, Récolte, Artisans et Mes artisans défilent comme celle des métiers de Blizzard ; un artisan choisi depuis Artisans arrive sélectionné dans Commande ; le bouton d'aide passe au-dessus du portrait et ne se cache plus derrière la Route ; Manquantes n'affiche plus l'exemplaire de l'autre camp d'une recette jumelle ; la Route puise dans tes sacs avant l'hôtel des ventes ; ouvrir le lien de métier d'un autre joueur ne range plus ses recettes dans les tiennes."] =
        "Además: las listas de Pedido, Recolección, Artesanos y Mis artesanos se desplazan como la lista de profesiones de Blizzard; un artesano elegido desde Artesanos llega seleccionado en Pedido; el botón de ayuda está sobre el retrato y ya no se esconde detrás de la Ruta; Faltantes ya no muestra el ejemplar de la otra facción de una receta gemela; la Ruta usa tus bolsas antes que la casa de subastas; abrir el enlace de profesión de otro jugador ya no guarda sus recetas entre las tuyas.",
    -- v1.40.0
    ["Tes commandes sur Commerce, et l'addon sans communauté"] =
        "Tus pedidos en Comercio, y el addon sin comunidad",
    ["Coche « Annoncer en Commerce » en postant une commande à tous : l'addon écrit aussi une ligne sur Trade (Services), dans une capitale, que tout le monde lit. Les joueurs de l'addon, même inconnus, reçoivent la vraie commande en quelques secondes ; les autres peuvent te chuchoter. Clic droit sur la commande dans le Carnet pour la rappeler, une fois par quart d'heure."] =
        "Marca «Anunciar en Comercio» al publicar un pedido para todos: el addon escribe también una línea en Comercio (Servicios), en una capital, que todos pueden leer. Los usuarios del addon, incluso desconocidos, reciben el pedido real en segundos; los demás pueden susurrarte. Clic derecho sobre el pedido en el Libro para repetirlo, una vez cada cuarto de hora.",
    ["La même case, dans l'offre de « Chercher du travail », annonce ta dispo : une ligne « LFW » sur Trade (Services) quand tu l'actives, et les joueurs de l'addon reçoivent ton profil."] =
        "La misma casilla, en la oferta de «Buscar trabajo», anuncia tu disponibilidad: una línea «LFW» en Comercio (Servicios) cuando la activas, y los usuarios del addon reciben tu perfil.",
    ["L'addon marche sans la communauté Crafting Order PVE et ne t'en envoie plus le lien. Les artisans se trouvent par les amis, la guilde, tes cercles, les annonces sur Commerce et la salle de découverte, où les joueurs de l'addon se disent bonjour (« /co channel room off » pour la quitter)."] =
        "El addon funciona sin la comunidad Crafting Order PVE y ya no te envía su enlace. Los artesanos se encuentran por amigos, hermandad, tus círculos, los anuncios en Comercio y la sala de descubrimiento, donde los usuarios del addon se saludan («/co channel room off» para salir).",
    ["Aussi : l'addon ne crie plus de ping, que Forever refusait sans rien dire ; « /co note » prépare le texte de tes métiers à coller dans ta note de membre d'une communauté, et l'onglet Artisans affiche la note des autres."] =
        "Además: el addon ya no grita un ping, que Forever rechazaba en silencio; «/co note» prepara el texto de tus profesiones para pegarlo en tu nota de miembro de una comunidad, y la pestaña Artesanos muestra las notas de los demás.",
}

for k, v in pairs(news) do L[k] = v end
